      const right = ask === 0 ? `${MC[hi]}CO<sub>3</sub>` : `${MC[lo]}CO<sub>3</sub>`; const wrong = ask === 0 ? `${MC[lo]}CO<sub>3</sub>` : `${MC[hi]}CO<sub>3</sub>`;
      const o = shuffleOpts(rng, right, [wrong, 'Both have the same stability', 'Cannot be predicted']);
