      const kind = choose(rng, ['sulphate', 'hydroxide']); const MC = ['Mg', 'Ca', 'Sr', 'Ba']; let i = int(rng, 0, 3), j = int(rng, 0, 2); if (j >= i) j++;
      const hi = Math.max(i, j), lo = Math.min(i, j); const f = (m) => kind === 'sulphate' ? `${m}SO<sub>4</sub>` : `${m}(OH)<sub>2</sub>`;
